const items = $input.all();
const review = items[0]?.json.review;
if (items.length !== 1 || !review || Object.keys(review).length !== 2 ||
    typeof review.case_ref !== 'string' || !/^[A-Za-z0-9][A-Za-z0-9_-]{0,39}$/.test(review.case_ref) ||
    typeof review.review_id !== 'string' || !/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i.test(review.review_id)) {
  throw new Error('Expected one case reference and review UUID.');
}
return [{json: {
  event_key: JSON.stringify(['vapi-review-v1', review.case_ref, review.review_id.toLowerCase()]),
  content: `Vapi text chat requested a human review for case ${review.case_ref}.`,
}}];

const items = $input.all();
if (items.length !== 1) throw new Error('Expected one Telbox inbox result. No message requested.');
const body = items[0]?.json;
if (!body || typeof body !== 'object' || Array.isArray(body) || body.error || body.isError) {
  throw new Error('Telbox inbox discovery failed. No message requested.');
}
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
function valid(value) {
  return value && typeof value === 'object' && !Array.isArray(value)
    && ['ready', 'setup_required'].includes(value.status)
    && value.owner_approval_required === true
    && value.destination === 'Notes to Self' && typeof value.next_step === 'string'
    && (value.status === 'ready'
      ? typeof value.thread_id === 'string' && uuid.test(value.thread_id)
      : value.thread_id === null);
}
const candidates = [];
if (body.structuredContent !== undefined) {
  if (!valid(body.structuredContent)) throw new Error('Invalid structured inbox result. No message requested.');
  candidates.push(body.structuredContent);
}
if (body.content !== undefined && !Array.isArray(body.content)) {
  throw new Error('Invalid inbox content blocks. No message requested.');
}
for (const block of body.content ?? []) {
  if (!block || block.type !== 'text') continue;
  let value = block.text;
  if (typeof value === 'string') {
    try { value = JSON.parse(value); } catch { continue; }
  }
  if (valid(value)) candidates.push(value);
}
if (!candidates.length) throw new Error('No valid Telbox inbox result. No message requested.');
const inbox = candidates[0];
if (candidates.some(value => ['status', 'thread_id', 'owner_approval_required', 'next_step'].some(key => value[key] !== inbox[key]))) {
  throw new Error('Conflicting Telbox inbox results. No message requested.');
}
if (inbox.status !== 'ready') {
  const instruction = inbox.next_step.trim() || 'Check inbox setup in the receiving Telbox account.';
  throw new Error(instruction + ' No message requested.');
}
// One event was validated before discovery; never take message text or an event ID from remote output.
const events = $('Validate one event').all();
if (events.length !== 1) throw new Error('Expected one validated event. No message requested.');
const event = events[0]?.json;
if (!event || typeof event.content !== 'string' || !event.content.trim() || Array.from(event.content).length > 8192
    || typeof event.client_message_id !== 'string' || !/^[A-Za-z0-9._:-]{1,64}$/.test(event.client_message_id)) {
  throw new Error('Invalid original event. No message requested.');
}
return [{ json: {
  thread_id: inbox.thread_id,
  content: event.content,
  client_message_id: event.client_message_id,
} }];

const items = $input.all();
if (items.length !== 1) throw new Error('Unknown Telbox outcome: expected one result. Do not automatically repeat the message request.');
const body = items[0]?.json;
if (!body || typeof body !== 'object' || body.error || body.isError) {
  throw new Error('Telbox request failed or its outcome is unknown. Inspect the execution and Telbox drafts before retrying.');
}
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const states = {
  pending_approval: 'awaiting_owner_approval',
  approved: 'approval_recorded_delivery_unverified',
  executed: 'proposal_executed_delivery_unverified',
  rejected: 'owner_rejected',
  expired: 'proposal_expired',
};
function valid(value) {
  return value && typeof value === 'object' && !Array.isArray(value)
    && typeof value.draft_id === 'string' && uuid.test(value.draft_id)
    && typeof value.approval_request_id === 'string' && uuid.test(value.approval_request_id)
    && Object.hasOwn(states, value.status);
}
const candidates = [];
if (body.structuredContent !== undefined) {
  if (!valid(body.structuredContent)) throw new Error('Invalid structured Telbox result; outcome unverified.');
  candidates.push(body.structuredContent);
}
for (const block of body.content ?? []) {
  if (block.type !== 'text') continue;
  let value = block.text;
  // n8n MCP Client parses JSON text blocks, while older transports may leave strings.
  if (typeof value === 'string') {
    try { value = JSON.parse(value); } catch { continue; }
  }
  if (valid(value)) candidates.push(value);
}
if (!candidates.length) throw new Error('No valid Telbox proposal receipt. Do not treat this execution as delivery.');
const receipt = candidates[0];
if (candidates.some(value => ['draft_id', 'approval_request_id', 'status'].some(key => value[key] !== receipt[key]))) {
  throw new Error('Conflicting Telbox receipts; do not resume or repeat the action.');
}
return [{ json: {
  draft_id: receipt.draft_id,
  approval_request_id: receipt.approval_request_id,
  proposal_status: receipt.status,
  outcome: states[receipt.status],
  native_delivery: 'not_verified',
  workflow_may_resume: false,
  continuation: 'not_implemented',
} }];
